/** Locked PRIME visual system. */
public final class CortexUi {
    public static final int BG=Color.rgb(7,7,8),SURFACE=Color.rgb(15,15,16),SURFACE_2=Color.rgb(20,20,22),SURFACE_3=Color.rgb(26,26,28),TEXT=Color.rgb(244,243,239),MUTED=Color.rgb(164,163,160),FAINT=Color.rgb(103,103,106);
    public static final int RED=Color.rgb(255,72,62),ORANGE=Color.rgb(255,146,42),YELLOW=Color.rgb(241,188,52),GREEN=Color.rgb(105,194,82);
    public static final int ACCENT=RED,SIGNAL=RED,AMBER=ORANGE,SAGE=GREEN,INFO=GREEN,VIOLET=YELLOW,BORDER=Color.rgb(45,45,48),BORDER_SOFT=Color.rgb(31,31,34),HAIRLINE=Color.argb(40,255,255,255),COPPER=ORANGE,CORAL=RED,GOLD=YELLOW;
    private CortexUi(){}
    public static int dp(Activity a,int v){return(int)(v*a.getResources().getDisplayMetrics().density+.5f);}
    public static void applyWindow(Activity a){Window w=a.getWindow();w.setStatusBarColor(BG);w.setNavigationBarColor(BG);if(Build.VERSION.SDK_INT>=29)w.setNavigationBarContrastEnforced(false);if(Build.VERSION.SDK_INT>=23)w.getDecorView().setSystemUiVisibility(0);}
    public static void fitSystemBars(Activity a,View root){final int pl=root.getPaddingLeft(),pt=root.getPaddingTop(),pr=root.getPaddingRight(),pb=root.getPaddingBottom();root.setOnApplyWindowInsetsListener((v,insets)->{int l=0,t=0,r=0,b=0;if(Build.VERSION.SDK_INT>=30){android.graphics.Insets x=insets.getInsets(WindowInsets.Type.systemBars());l=x.left;t=x.top;r=x.right;b=x.bottom;}else{l=insets.getSystemWindowInsetLeft();t=insets.getSystemWindowInsetTop();r=insets.getSystemWindowInsetRight();b=insets.getSystemWindowInsetBottom();}v.setPadding(pl+l,pt+t,pr+r,pb+b);return insets;});root.requestApplyInsets();}
    public static GradientDrawable round(Activity a,int fill,int stroke,int radius){GradientDrawable g=new GradientDrawable();g.setColor(fill);g.setCornerRadius(dp(a,radius));if(stroke!=Color.TRANSPARENT)g.setStroke(dp(a,1),stroke);return g;}
    public static GradientDrawable gradient(Activity a,int start,int end,int stroke,int radius){GradientDrawable g=new GradientDrawable(GradientDrawable.Orientation.TOP_BOTTOM,new int[]{start,end});g.setCornerRadius(dp(a,radius));if(stroke!=Color.TRANSPARENT)g.setStroke(dp(a,1),stroke);return g;}
    public static GradientDrawable velvet(Activity a,int radius){return gradient(a,SURFACE_2,SURFACE,HAIRLINE,radius);}public static GradientDrawable matte(Activity a,int radius){return round(a,SURFACE,HAIRLINE,radius);}public static View divider(Activity a){View v=new View(a);v.setBackgroundColor(BORDER_SOFT);return v;}
    public static<T extends View>T raised(Activity a,T v,int e){if(Build.VERSION.SDK_INT>=21){v.setElevation(dp(a,e));v.setTranslationZ(0f);}return v;}public static CortexGlyphView glyph(Activity a,String k,int c,boolean d){CortexGlyphView g=new CortexGlyphView(a,k,c,d);raised(a,g,4);return g;}
    public static View pressable(Activity a,View v,GradientDrawable base){if(Build.VERSION.SDK_INT>=21)v.setBackground(new RippleDrawable(ColorStateList.valueOf(Color.argb(18,255,255,255)),base,null));else v.setBackground(base);v.setClickable(true);v.setFocusable(true);raised(a,v,3);v.setOnTouchListener((x,e)->{if(Build.VERSION.SDK_INT>=21){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){x.setTranslationZ(-dp(a,1));x.setScaleX(.992f);x.setScaleY(.992f);}else if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){x.setTranslationZ(0);x.setScaleX(1);x.setScaleY(1);}}return false;});return v;}
    public static TextView text(Activity a,String s,int sp,int c){TextView v=new TextView(a);v.setTextSize(sp);v.setTextColor(c);v.setLineSpacing(0,1.05f);CortexTextUi.setReadable(v,s==null?"":s);return v;}public static TextView plain(Activity a,String s,int sp,int c){TextView v=new TextView(a);v.setTextSize(sp);v.setTextColor(c);CortexTextUi.setPlain(v,s==null?"":s);return v;}public static void medium(TextView v){v.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));}public static void bold(TextView v){v.setTypeface(Typeface.create("sans-serif",Typeface.BOLD));}
    public static LinearLayout card(Activity a,int r){LinearLayout c=new LinearLayout(a);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(a,16),dp(a,15),dp(a,16),dp(a,15));c.setBackground(velvet(a,r));raised(a,c,4);return c;}
    public static TextView chip(Activity a,String l,int c,boolean strong){TextView v=plain(a,l,strong?11:10,c);if(strong)medium(v);v.setGravity(Gravity.CENTER);v.setPadding(dp(a,11),0,dp(a,11),0);v.setBackground(round(a,Color.argb(strong?18:10,Color.red(c),Color.green(c),Color.blue(c)),Color.argb(strong?86:58,Color.red(c),Color.green(c),Color.blue(c)),999));raised(a,v,strong?3:2);return v;}
    public static TextView section(Activity a,String t){TextView h=plain(a,t,11,MUTED);medium(h);h.setPadding(0,dp(a,22),0,dp(a,9));return h;}public static TextView action(Activity a,String l,int c,boolean filled){TextView b=plain(a,l,12,c);medium(b);b.setGravity(Gravity.CENTER);b.setPadding(dp(a,14),0,dp(a,14),0);pressable(a,b,round(a,Color.argb(filled?22:8,Color.red(c),Color.green(c),Color.blue(c)),Color.argb(filled?110:64,Color.red(c),Color.green(c),Color.blue(c)),15));raised(a,b,filled?5:3);return b;}
    public static int semanticFor(String key){if(key==null)return RED;String k=key.toLowerCase();if(k.contains("wait")||k.contains("remind"))return ORANGE;if(k.contains("decision"))return YELLOW;if(k.contains("people")||k.contains("project")||k.contains("memory")||k.contains("info")||k.contains("useful")||k.contains("complete"))return GREEN;if(k.contains("input")||k.contains("capture")||k.contains("play")||k.contains("change"))return ORANGE;return RED;}

    /** One navigation shell for every V2 surface. */
    public static void addBottomNav(Activity a,LinearLayout root,String selected,Runnable ignored){String current=primeKey(selected);LinearLayout bar=new LinearLayout(a);bar.setGravity(Gravity.CENTER);bar.setPadding(dp(a,8),dp(a,4),dp(a,8),dp(a,7));bar.setBackground(round(a,Color.rgb(8,9,12),Color.argb(30,255,255,255),20));addNav(a,bar,"today","Today",current,CompactTodayActivity.class);addNav(a,bar,"memory","Memory",current,ProposalPeopleProjectsActivity.class);addNav(a,bar,"capture","Capture",current,ProposalCaptureActivity.class);addNav(a,bar,"cortex","Cortex",current,ProposalAskCortexActivity.class);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(a,64));p.setMargins(dp(a,12),dp(a,4),dp(a,12),dp(a,8));root.addView(bar,p);fitSystemBars(a,root);}
    private static String primeKey(String s){if("home".equals(s)||"focus".equals(s)||"brief".equals(s)||"today".equals(s))return"today";if("vault".equals(s)||"people".equals(s)||"memory".equals(s))return"memory";if("ask".equals(s)||"brain".equals(s)||"cortex".equals(s))return"cortex";if("input".equals(s)||"capture".equals(s))return"capture";return s==null?"":s;}
    private static int navColor(String k){if("today".equals(k))return RED;if("memory".equals(k))return GREEN;if("capture".equals(k))return ORANGE;return YELLOW;}
    private static void addNav(Activity a,LinearLayout bar,String key,String label,String selected,Class<?> target){boolean on=key.equals(selected);int color=navColor(key);TextView v=plain(a,label,9,on?color:MUTED);v.setGravity(Gravity.CENTER);if(on)v.setBackground(round(a,Color.argb(22,Color.red(color),Color.green(color),Color.blue(color)),Color.argb(80,Color.red(color),Color.green(color),Color.blue(color)),14));else v.setOnClickListener(x->{try{Intent i=new Intent(a,target);i.addFlags(Intent.FLAG_ACTIVITY_REORDER_TO_FRONT|Intent.FLAG_ACTIVITY_SINGLE_TOP);a.startActivity(i);}catch(Throwable ignored){}});bar.addView(v,new LinearLayout.LayoutParams(0,-1,1));}
}
